style.css:
@-moz-document domain("google.com") {
/* ── CORE PALETTE ───────────────────────── */
  :root {
    --g-bg:        #1a0000;
    --g-surface:   #220808;
    --g-panel:     #2a0a0a;
    --g-card:      #300b0b;
    --g-border:    rgba(160, 0, 0, 0.45);
    --g-red:       #cc2020;
    --g-red-vivid: #e53030;
    --g-red-mid:   #b22222;
    --g-text:      #ffe4e4;
    --g-muted:     #c8a0a0;
    --g-hint:      #9a7070;
    --g-link:      #ff7070;
    --g-link-vis:  #cc5555;
    --g-poly:      linear-gradient(135deg, #8b0000 0%, #5a0000 30%, #6e0000 50%, #9a1010 70%, #7a0000 100%);
  }

  /* ── PAGE BACKGROUND ────────────────────── */
  html, body {
    background-color: var(--g-bg) !important;
    color: var(--g-text) !important;
  }

  /* ── HEADER / TOP BAR ───────────────────── */
  #gb, #sfcnt, header, #searchform,
  .o3j99.LLD4me, .o3j99.qarstb,
  [data-hveid] > div:first-child,
  .appbar, #hdtb, .webResult .action-menu {
    background: var(--g-surface) !important;
    border-bottom: 1px solid var(--g-border) !important;
  }

  /* Google logo area */
  #lga, #hplogo { filter: hue-rotate(330deg) saturate(2) brightness(0.85) !important; }

  /* ── SEARCH BAR ─────────────────────────── */
  .SDkEP, .a4bIc, form[role="search"],
  .RNNXgb, .SDkEP .Ax4B8, .aAjR3b .K2dAFb,
  input[name="q"], .gLFyf {
    background: var(--g-panel) !important;
    color: var(--g-text) !important;
    border: 1px solid var(--g-border) !important;
    caret-color: var(--g-red-vivid) !important;
  }

  /* Search bar wrapper / pill */
  .SDkEP, .RNNXgb, .A8SBwf, .aAjR3b {
    background: var(--g-panel) !important;
    border: 1px solid var(--g-border) !important;
    box-shadow: none !important;
  }

  /* Search bar on focus */
  .SDkEP:focus-within, .RNNXgb:focus-within,
  .A8SBwf:focus-within, .aAjR3b:focus-within {
    border-color: var(--g-red) !important;
    box-shadow: 0 0 0 2px rgba(180,0,0,0.25) !important;
  }

  /* Search input text */
  input[name="q"], .gLFyf, .gsfi {
    background: transparent !important;
    color: var(--g-text) !important;
  }

  input[name="q"]::placeholder, .gLFyf::placeholder {
    color: var(--g-hint) !important;
  }

  /* Search autocomplete dropdown */
  .aajZCb, ul.aajZCb, .erkvQe,
  .UUbT9, .sbdd .sbfc {
    background: var(--g-panel) !important;
    border: 1px solid var(--g-border) !important;
    box-shadow: none !important;
  }

  .sbct, .sbl1, .sbl2, .sbis,
  .erkvQe li, .UUbT9 li {
    color: var(--g-text) !important;
  }

  .sbct:hover, .erkvQe li:hover,
  .UUbT9 li:hover, .sbHob:hover {
    background: rgba(139,0,0,0.3) !important;
  }

  /* ── SEARCH BUTTONS ─────────────────────── */
  input[value="Google Search"],
  input[value="I'm Feeling Lucky"],
  .Tg7LZd, .z1asCe, .nOl28e,
  .FPdoLc input[type="submit"] {
    background: var(--g-surface) !important;
    color: var(--g-muted) !important;
    border: 1px solid var(--g-border) !important;
  }

  input[value="Google Search"]:hover,
  input[value="I'm Feeling Lucky"]:hover,
  .Tg7LZd:hover {
    background: rgba(139,0,0,0.4) !important;
    border-color: var(--g-red) !important;
    color: var(--g-text) !important;
  }

  /* ── NAVIGATION TABS (All/Images/News…) ─── */
  #hdtb, .crJ18e, .LatpMc,
  .T47uwc, .ndhY8e, .rQEFy {
    background: var(--g-surface) !important;
    border-bottom: 1px solid var(--g-border) !important;
  }

  /* Tab items */
  .T47uwc a, .hdtb-mitem a, .LatpMc a,
  .MUFPAc, .z4P7Td {
    color: var(--g-muted) !important;
  }

  /* Active tab */
  .T47uwc .hdtb-mitem.hdtb-msel,
  .rQEFy .MUFPAc.ab_selected,
  .hdtb-mitem.hdtb-msel > a,
  .z4P7Td.LatE2d {
    color: var(--g-red-vivid) !important;
    border-bottom: 3px solid var(--g-red-vivid) !important;
  }

  /* Tab hover */
  .T47uwc a:hover, .hdtb-mitem a:hover,
  .MUFPAc:hover {
    color: var(--g-text) !important;
    background: rgba(139,0,0,0.2) !important;
  }

  /* ── TOOLS / FILTER BAR ─────────────────── */
  .ndhY8e, .crJ18e, .P6VGId {
    background: var(--g-surface) !important;
  }

  .YmvwI, .zWfAef .ndhY8e {
    background: var(--g-panel) !important;
    border: 1px solid var(--g-border) !important;
    color: var(--g-text) !important;
  }

  /* ── SEARCH RESULTS ─────────────────────── */
  #search, #rso, #rcnt, #center_col,
  .srg, .g, .rc {
    background: transparent !important;
  }

  /* Result cards */
  .g, .rc, .tF2Cxc, .yuRUbf,
  .IsZvec, .kvH3mc, .ULSxyf {
    background: var(--g-card) !important;
    border: 1px solid var(--g-border) !important;
    border-radius: 8px !important;
    margin-bottom: 10px !important;
    padding: 14px !important;
  }

  /* Result title links */
  .yuRUbf a, h3.LC20lb,
  .DKV0Md, .cfxYMc {
    color: var(--g-link) !important;
  }

  .yuRUbf a:visited, h3.LC20lb:visited {
    color: var(--g-link-vis) !important;
  }

  .yuRUbf a:hover h3 {
    text-decoration: underline !important;
    color: #ff9090 !important;
  }

  /* URL breadcrumb */
  .TbwUpd, .tjvcx, .NJjxre,
  cite, .qzEoUe {
    color: var(--g-hint) !important;
  }

  /* Snippet / description text */
  .VwiC3b, .MUxGbd, .yDYNvb,
  .lEBKkf, .IsZvec span {
    color: var(--g-muted) !important;
  }

  /* ── KNOWLEDGE PANEL / CARDS ────────────── */
  .kp-wholepage, .kp-blk, .xpdopen .ifM9O,
  .KgFSCb, .IZ6rdc, .osrp-blk,
  .wDYxhc, .yp1CPe, .Wnoohf {
    background: var(--g-card) !important;
    border: 1px solid var(--g-border) !important;
    border-radius: 8px !important;
    color: var(--g-text) !important;
  }

  .kno-ecr-pt, .qrShPb, .wx62f,
  .kno-ftr, .kno-fb-ctx {
    color: var(--g-muted) !important;
  }

  /* ── FEATURED SNIPPET ───────────────────── */
  .xpdopen, .ifM9O, .FM1Efc,
  .c2xzTb, .Wnoohf .wDYxhc {
    background: var(--g-card) !important;
    border: 1px solid var(--g-border) !important;
    border-left: 3px solid var(--g-red) !important;
    border-radius: 8px !important;
  }

  /* ── PEOPLE ALSO ASK ────────────────────── */
  .related-question-pair, .g.kno-kp,
  .dnXCYb, .JlqpRe {
    background: var(--g-panel) !important;
    border: 1px solid var(--g-border) !important;
    border-radius: 6px !important;
  }

  .dnXCYb .iDjcJe, .JlqpRe .iDjcJe {
    color: var(--g-text) !important;
  }

  /* ── RIGHT SIDEBAR ──────────────────────── */
  #rhs, #rhscol {
    background: transparent !important;
  }

  /* ── PAGINATION ─────────────────────────── */
  #botstuff, #foot, .AaVjTc td,
  .fl a, #navcnt td {
    background: var(--g-surface) !important;
    color: var(--g-muted) !important;
  }

  /* Current page number */
  .YyVfkd {
    background: var(--g-red) !important;
    color: #ffe4e4 !important;
    border-radius: 50% !important;
  }

  /* Page number links */
  .fl a, #navcnt a {
    color: var(--g-link) !important;
  }

  /* ── GENERAL LINKS ──────────────────────── */
  a:not([class]), a.fl, .ab_button {
    color: var(--g-link) !important;
  }

  /* ── DIVIDERS / BORDERS ─────────────────── */
  hr, .bbVIE, .xpdclose::before,
  .xpdopen::before {
    border-color: var(--g-border) !important;
  }

  /* ── SCROLLBAR ──────────────────────────── */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: var(--g-bg); }
  ::-webkit-scrollbar-thumb { background: #6b0000; border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--g-red-mid); }

  /* ── IMAGE SEARCH RESULTS ───────────────── */
  #islrg, .isv-r, .isv-r .irc_mutc {
    background: var(--g-card) !important;
    border-radius: 6px !important;
  }

  /* ── GOOGLE HOMEPAGE ONLY ───────────────── */
  #gsr, #searchform, .o3j99 {
    background: var(--g-surface) !important;
  }

  /* ── SELECTION HIGHLIGHT ────────────────── */
  ::selection {
    background: rgba(180, 0, 0, 0.45) !important;
    color: #ffe4e4 !important;
  }
}
